384	func resolveCloudProxyBaseURL(rawOverride string, runMode string) (baseURL string, signingHost string, overridden bool, err error) {
385		baseURL = defaultCloudProxyBaseURL
386		signingHost = defaultCloudProxySigningHost
387	
388		rawOverride = strings.TrimSpace(rawOverride)
389		if rawOverride == "" {
390			return baseURL, signingHost, false, nil
391		}
392	
393		u, err := url.Parse(rawOverride)
394		if err != nil {
395			return "", "", false, fmt.Errorf("invalid URL: %w", err)
396		}
397		if u.Scheme == "" || u.Host == "" {
398			return "", "", false, fmt.Errorf("invalid URL: scheme and host are required")
399		}
400		if u.User != nil {
401			return "", "", false, fmt.Errorf("invalid URL: userinfo is not allowed")
402		}
403		if u.Path != "" && u.Path != "/" {
404			return "", "", false, fmt.Errorf("invalid URL: path is not allowed")
405		}
406		if u.RawQuery != "" || u.Fragment != "" {
407			return "", "", false, fmt.Errorf("invalid URL: query and fragment are not allowed")
408		}
409	
410		host := u.Hostname()
411		if host == "" {
412			return "", "", false, fmt.Errorf("invalid URL: host is required")
413		}
414	
415		loopback := isLoopbackHost(host)
416		if runMode == gin.ReleaseMode && !loopback {
417			return "", "", false, fmt.Errorf("non-loopback cloud override is not allowed in release mode")
418		}
419		if !loopback && !strings.EqualFold(u.Scheme, "https") {
420			return "", "", false, fmt.Errorf("non-loopback cloud override must use https")
421		}
422	
423		u.Path = ""
424		u.RawPath = ""
425		u.RawQuery = ""
426		u.Fragment = ""
427	
428		return u.String(), strings.ToLower(host), true, nil
429	}
