468	func copyProxyResponseBody(dst http.ResponseWriter, src io.Reader) error {
469		flusher, canFlush := dst.(http.Flusher)
470		buf := make([]byte, 32*1024)
471	
472		for {
473			n, err := src.Read(buf)
474			if n > 0 {
475				if _, writeErr := dst.Write(buf[:n]); writeErr != nil {
476					return writeErr
477				}
478				if canFlush {
479					// TODO(drifkin): Consider conditional flushing so non-streaming
480					// responses don't flush every write and can optimize throughput.
481					flusher.Flush()
482				}
483			}
484	
485			if err != nil {
486				if err == io.EOF {
487					return nil
488				}
489				return err
490			}
491		}
492	}
