513	func (w *jsonlFramingResponseWriter) FlushPending() error {
514		trailing := bytes.TrimSpace(w.pending)
515		w.pending = nil
516		if len(trailing) == 0 {
517			return nil
518		}
519	
520		_, err := w.ResponseWriter.Write(trailing)
521		return err
522	}
