524	func (w *jsonlFramingResponseWriter) flushCompleteLines() error {
525		for {
526			newline := bytes.IndexByte(w.pending, '\n')
527			if newline < 0 {
528				return nil
529			}
530	
531			line := bytes.TrimSpace(w.pending[:newline])
532			w.pending = w.pending[newline+1:]
533			if len(line) == 0 {
534				continue
535			}
536	
537			if _, err := w.ResponseWriter.Write(line); err != nil {
538				return err
539			}
540		}
