362	// reportMCPStates tells the user what happened to each configured server, in
363	// the same voice as the skill diagnostics above. A server that is silently
364	// missing its tools is worse than one that explains itself.
365	func reportMCPStates(states []mcp.ServerState) {
366		var connected []string
367		for _, state := range states {
368			switch state.Status {
369			case mcp.StatusConnected:
370				connected = append(connected, fmt.Sprintf("%s (%d tools)", state.Name, len(state.Tools)))
371				for _, skipped := range state.Skipped {
372					fmt.Fprintf(os.Stderr, "\033[1mwarning:\033[0m mcp %s: skipped tool %q: %s\n", state.Name, skipped.Name, skipped.Reason)
373				}
374			case mcp.StatusNeedsApproval:
375				fmt.Fprintf(os.Stderr, "\033[1mwarning:\033[0m mcp %s is not approved to run: %s\n", state.Name, state.Spec.Summary())
376			case mcp.StatusNeedsSignIn:
377				// Not a failure, and not answered by retrying: say what to do.
378				fmt.Fprintf(os.Stderr, "\033[1mwarning:\033[0m mcp %s needs you to sign in: ollama mcp login %s\n", state.Name, state.Name)
379			case mcp.StatusInvalid:
380				fmt.Fprintf(os.Stderr, "\033[1mwarning:\033[0m mcp %s is misconfigured: %v\n", state.Name, state.Err)
381			case mcp.StatusFailed:
382				fmt.Fprintf(os.Stderr, "\033[1mwarning:\033[0m mcp %s unavailable: %v\n", state.Name, state.Err)
383			}
384		}
385		if len(connected) > 0 {
386			fmt.Fprintf(os.Stderr, "Loaded MCP servers: %s\n", strings.Join(connected, ", "))
387		}
388	}
