179	func proxyCloudRequestWithPath(c *gin.Context, body []byte, path string, disabledOperation string) {
180		if disabled, _ := internalcloud.Status(); disabled {
181			c.JSON(http.StatusForbidden, gin.H{"error": internalcloud.DisabledError(disabledOperation)})
182			return
183		}
184	
185		baseURL, err := url.Parse(cloudProxyBaseURL)
186		if err != nil {
187			c.JSON(http.StatusInternalServerError, gin.H{"error": err.Error()})
188			return
189		}
190	
191		targetURL := baseURL.ResolveReference(&url.URL{
192			Path:     path,
193			RawQuery: c.Request.URL.RawQuery,
194		})
195	
196		outReq, err := http.NewRequestWithContext(c.Request.Context(), c.Request.Method, targetURL.String(), bytes.NewReader(body))
197		if err != nil {
198			c.JSON(http.StatusInternalServerError, gin.H{"error": err.Error()})
199			return
200		}
201	
202		copyProxyRequestHeaders(outReq.Header, c.Request.Header)
203		if clientVersion := strings.TrimSpace(version.Version); clientVersion != "" {
204			outReq.Header.Set(cloudProxyClientVersionHeader, clientVersion)
205		}
206		if outReq.Header.Get("Content-Type") == "" && len(body) > 0 {
207			outReq.Header.Set("Content-Type", "application/json")
208		}
209	
210		if err := cloudProxySignRequest(outReq.Context(), outReq); err != nil {
211			slog.Warn("cloud proxy signing failed", "error", err)
212			writeCloudUnauthorized(c)
213			return
214		}
215	
216		// TODO(drifkin): Add phase-specific proxy timeouts.
217		// Connect/TLS/TTFB should have bounded timeouts, but once streaming starts
218		// we should not enforce a short total timeout for long-lived responses.
219		resp, err := http.DefaultClient.Do(outReq)
220		if err != nil {
221			c.JSON(http.StatusBadGateway, gin.H{"error": err.Error()})
222			return
223		}
224		defer resp.Body.Close()
225	
226		copyProxyResponseHeaders(c.Writer.Header(), resp.Header)
227		c.Status(resp.StatusCode)
228	
229		var bodyWriter http.ResponseWriter = c.Writer
230		var framedWriter *jsonlFramingResponseWriter
231		// TEMP(drifkin): only needed on the cloud-proxied first leg of Anthropic
232		// web_search fallback (which is a path we're removing soon). Local
233		// /v1/messages writes one JSON value per streamResponse callback directly
234		// into WebSearchAnthropicWriter, but this proxy copy loop may coalesce
235		// multiple jsonl records into one Write.  WebSearchAnthropicWriter currently
236		// unmarshals one JSON value per Write.
237		if path == "/api/chat" && resp.StatusCode == http.StatusOK && c.GetBool(legacyCloudAnthropicKey) {
238			framedWriter = &jsonlFramingResponseWriter{ResponseWriter: c.Writer}
239			bodyWriter = framedWriter
240		}
241	
242		err = copyProxyResponseBody(bodyWriter, resp.Body)
243		if err == nil && framedWriter != nil {
244			err = framedWriter.FlushPending()
245		}
246		if err != nil {
247			ctxErr := c.Request.Context().Err()
248			if errors.Is(err, context.Canceled) && errors.Is(ctxErr, context.Canceled) {
249				slog.Debug(
250					"cloud proxy response stream closed by client",
251					"path", c.Request.URL.Path,
252					"status", resp.StatusCode,
253				)
254				return
255			}
256	
257			slog.Warn(
258				"cloud proxy response copy failed",
259				"path", c.Request.URL.Path,
260				"upstream_path", path,
261				"status", resp.StatusCode,
262				"request_context_canceled", ctxErr != nil,
263				"request_context_err", ctxErr,
264				"error", err,
265			)
